#include "source-delta.hpp"
#include <vector>
#include <cstdio>
#include <cstdlib>
using namespace showai_boundary;
static void require(bool b,const char*label,PolynomialContext&c){if(!b||c.numbers.status){std::fprintf(stderr,"source delta failure %s status=%u poly=%llu limb=%llu\n",label,c.numbers.status,(unsigned long long)c.polynomial.operations,(unsigned long long)c.numbers.work);std::abort();}}
static void rectangle(SAInkPathCommand*out,double x){out[0]={SA_INK_MOVE,0,{x,0}};out[1]={SA_INK_LINE,0,{x+1,0}};out[2]={SA_INK_LINE,0,{x+1,1}};out[3]={SA_INK_LINE,0,{x,1}};out[4]={SA_INK_CLOSE,0,{}};}
static bool inside(Graph&g,int64_t x){return normalized_winding(g,{Q::from_signed(*g.context(),x*2+1)/Q(2),Q::from_signed(*g.context(),1)/Q(2)})==1;}
int main(){std::vector<uint64_t>arena(16*1024*1024/8);PolynomialContext c;c.numbers.initialize(arena.data(),uint32_t(arena.size()*8),10000000000ull);c.polynomial.max_operations=50000000;{
 SABoundaryBudget b{};b.max_commands=20;b.max_curves=8;b.max_pairs=100;b.max_cuts=10000;b.max_edges=100;b.max_sources=10;b.max_paths=1;SABoundaryPath path{0,0,{0,0}};
 SAInkPathCommand commands[10];rectangle(commands,0);rectangle(commands+5,3);SABoundarySourceBlock sources[2]{};for(uint32_t i=0;i<2;i++){sources[i].key.words[0]=i+1;sources[i].first_command=i*5;sources[i].command_count=5;sources[i].affine[0]=sources[i].affine[3]=1;}
 Graph base(c,b);require(capture(base,&path,1,sources,2,commands,10),"actual immutable base capture",c);construct(base);require(base.edges.size()==8&&inside(base,0)&&inside(base,3),"actual original two-source graph",c);
 Graph next=base;SABoundarySourceBlock description=sources[1];description.first_command=0;SAInkPathCommand moved[5];rectangle(moved,6);{SourceDirty dirty(c.numbers);require(upsert_source(next,description,moved,5,dirty),"same key changed actual closed source",c);require(dirty.initialized,"closed removed/inserted support tracked",c);construct_delta(next,dirty);}require(next.metrics.classifications==4&&next.metrics.classification_cache_hits==4,"exact closed-support locality reuses unrelated source classifications",c);require(next.edges.size()==8&&inside(next,0)&&!inside(next,3)&&inside(next,6),"real moved source semantic graph",c);require(inside(base,0)&&inside(base,3)&&!inside(base,6),"old inflight base independent",c);
 uint64_t no_op=c.numbers.allocations;{SourceDirty dirty(c.numbers);require(upsert_source(next,description,moved,5,dirty)&&!dirty.initialized,"actual byte-equal source is unchanged",c);}require(c.numbers.allocations==no_op,"no source-key-only normalization or allocation",c);
 for(uint32_t i=0;i<64;i++){
  uint32_t slot=source_slot(next,description.key);require(slot!=no_index,"actual live source lookup",c);uint32_t index=static_cast<const Graph&>(next).source_table[slot]-1;
  {SourceDirty dirty(c.numbers);require(remove_source(next,index,dirty),"real causal source removal",c);description.key.words[0]=100+i;rectangle(moved,9+i*3);require(upsert_source(next,description,moved,5,dirty),"new key independent captured source reuses pool",c);construct_delta(next,dirty);}
  require(next.metrics.classifications==4&&next.metrics.classification_cache_hits==4,"tail classification bounded to actual changed source",c);require(next.active_sources==2&&next.active_commands==10&&next.curves.size()==8&&next.blocks.size()==2,"bounded actual source/curve pools",c);require(inside(next,0)&&inside(next,9+i*3)&&inside(base,3),"tombstone reuse source order and old lease remain correct",c);
 }
 SAInkPathCommand fresh_commands[10];rectangle(fresh_commands,0);rectangle(fresh_commands+5,198);SABoundarySourceBlock fresh_sources[2]={sources[0],description};fresh_sources[1].first_command=5;Graph full(c,b);capture(full,&path,1,fresh_sources,2,fresh_commands,10);construct(full);require(full.edges.size()==next.edges.size(),"incremental/full canonical exposed count",c);
 auto incremental=area(next,Q(0),Q(0),Q(200),Q(1)),canonical=area(full,Q(0),Q(0),Q(200),Q(1));require(incremental.lower==canonical.lower&&incremental.upper==canonical.upper&&incremental.lower==Q::from_signed(c.numbers,1)/Q(100),"incremental/full exact Green parity",c);
 uint64_t live=c.numbers.live_bytes;bool rejected=false;{Graph failed=next;SourceDirty dirty(c.numbers);SABoundarySourceBlock extra=description;extra.key.words[0]=99999;rectangle(moved,20000);rejected=!upsert_source(failed,extra,moved,5,dirty)&&c.numbers.status==SA_INK_CAPACITY;}c.numbers.begin_work(10000000000ull);require(rejected&&c.numbers.live_bytes==live,"actual budget failure releases all staging bytes",c);require(inside(next,198)&&inside(base,3),"complete old sources survive actual failed delta",c);
 std::printf("BOUNDARY_SOURCE_DELTA_COW_OK mutations=65 pool_curves=%u pool_blocks=%u\n",next.curves.size(),next.blocks.size());
 }require(c.numbers.live_bytes==0,"all source delta/inflight roots released",c);}
